def prepend(head, v):
    return Node(v, head)

dynamic-programming.code:
def fib(n: int) -> int:
    if n < 2:
        return n
    dp = [0, 1]
    for i in range(2, n + 1):
        dp.append(dp[i - 1] + dp[i - 2])
    return dp[n]

